/* State oracle for src/tu/grtcaptain.rs (generated by gen_target_stage.py): the game TU #included verbatim
 * (shipping contraction via run.py), every callee outside it a tracing stub, cases on a synthetic
 * state from the shared seeded stream. tests/tu_grtcaptain.rs replays them. */
#include "melee/gr/grtcaptain.c"
#include "oracle.h"
#include "tu_gr_common.h"
#include "tu_grtcaptain_stubs.inc"

static void state(void)
{
    printf("rs %u\n", ORS);
    printf("si %d %d\n", (int) stage_info.unk8C.b4, (int) stage_info.unk8C.b5);
    DUMPARENA();
    state_end();
}

#define FN(x) fnreg(#x, (void*) x)
int main(void)
{
    int c;
    arena_init();
    SIZE(Ground);
    SIZE(HSD_GObj);
    SIZE(HSD_JObj);
    SIZE(StageCallbacks);
    SIZE(StageData);
    reg("cb", grTCa_StageCallbacks, sizeof(grTCa_StageCallbacks));
    reg("sd", &grTCa_StageData, sizeof(grTCa_StageData));
    reg("dat", grTCa_StageData.data1, 16);
    FN(grTCaptain_OnDemoInit);
    FN(grTCaptain_OnInit);
    FN(grTCaptain_OnLoad);
    FN(grTCaptain_OnStart);
    FN(grTCaptain_8021FCFC);
    FN(grTCaptain_8021FD04);
    FN(grTCaptain_OnTouchLine);
    FN(grTCaptain_OnCheckShadowRender);
    FN(stageGObj0_OnInit);
    FN(grTCaptain_8021FE18);
    FN(grTCaptain_8021FE20);
    FN(grTCaptain_8021FE24);
    FN(stageGObj1_OnInit);
    FN(grTCaptain_8021FF08);
    FN(stageGObj1_GObjProc);
    FN(grTCaptain_8021FF30);
    FN(stageGObj2_OnInit);
    FN(grTCaptain_8021FE78);
    FN(stageGObj2_GObjProc);
    FN(grTCaptain_8021FEB4);
    fnreg("grDisplay_801C5DB0", (void*) grDisplay_801C5DB0);
    DUMP("cb", grTCa_StageCallbacks);
    DUMP("sd", grTCa_StageData);
    state_end();

    for (c = 0; c < 60; c++) { /* grTCaptain_8021FD04 and the callbacks it installs */
        CASE(c);
        rseed(100 + c);
        gr_reset();
        stage_info.unk8C.b4 = rnd() & 1;
        stage_info.unk8C.b5 = rnd() & 1;
        printf("r"); TRP(grTCaptain_8021FD04(c % 3)); printf("\n");
        state();
    }
    for (c = 0; c < 20; c++) { /* OnInit / OnStart / OnLoad / OnDemoInit */
        CASE(1000 + c);
        rseed(2000 + c);
        gr_reset();
        grTCaptain_OnInit();
        state();
        grTCaptain_OnStart();
        grTCaptain_OnLoad();
        grTCaptain_OnDemoInit((int) rnd());
        state();
    }
    for (c = 0; c < 12; c++) { /* every stage callback of the three gobjs */
        HSD_GObj* g;
        CASE(2000 + c);
        rseed(3000 + c);
        gr_reset();
        g = mkgobj();
        stageGObj0_OnInit(g); state();
        printf("r %d\n", (int) grTCaptain_8021FE18(g));
        grTCaptain_8021FE20(g); grTCaptain_8021FE24(g); state();
        stageGObj1_OnInit(g); state();
        printf("r %d\n", (int) grTCaptain_8021FF08(g));
        stageGObj1_GObjProc(g); grTCaptain_8021FF30(g); state();
        stageGObj2_OnInit(g); state();
        printf("r %d\n", (int) grTCaptain_8021FE78(g));
        stageGObj2_GObjProc(g); grTCaptain_8021FEB4(g); state();
        printf("r %d\n", (int) grTCaptain_8021FCFC());
        printf("r"); TRP(grTCaptain_OnTouchLine((int) rnd())); printf("\n");
        {
            Vec3 v;
            int a1;
            HSD_JObj* j;
            v.x = rf(); v.y = rf(); v.z = rf();
            a1 = (int) rnd();
            j = mkjobj();
            printf("r %d\n", (int) grTCaptain_OnCheckShadowRender(&v, a1, j));
        }
        state();
    }
    return 0;
}
